const aliases: Record<string, string> = {
  google_drive: "googledrive",
  gdrive: "googledrive",
  drive: "googledrive",
  cloudflare_r2: "cloudflare",
  r2: "cloudflare",
  backblaze_b2: "backblaze",
  b2: "backblaze",
  s3_storage: "s3",
  "1password": "onepassword",
  calendar: "googlecalendar",
  google_calendar: "googlecalendar",
  "apple-apps": "apple",
  "aws-knowledge": "aws",
  "brave-search": "brave",
  bravesearch: "brave",
  apollo: "apollographql",
  "cloudflare-docs": "cloudflare",
  cloudflaredocs: "cloudflare",
  "twilio-docs": "twilio",
  twiliodocs: "twilio",
  "microsoft-learn": "microsoft",
  microsoftlearn: "microsoft",
  "meta-ads": "meta",
  metaads: "meta",
  feishu: "lark",
  "firecrawl-local": "firecrawl",
  firecrawllocal: "firecrawl",
  dida365: "ticktick",
}

export function brandLogo(id: string): BrandLogoSpec | null {
  const normalized = id.toLowerCase().replace(/[^a-z0-9_]/g, "")
  const key = aliases[normalized] ?? aliases[id] ?? normalized
  return glyphs[key] ?? glyphs[id] ?? null
}
